head.script:
scwin.onpageload = function() {
    //정적 그리드를 위한 데이터 세팅 
    var jsonData = [{
        "col1": "20220127",
        "col2": "2",
        "col3": "3"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }];
    dataList2.setJSON(jsonData);
    //senseReader="false"인 정적 그리드 
    gridView2.setReadOnly("cell", 1, "col1", true);
    gridView2.setReadOnly("cell", 2, "col1", true);
    gridView2.setReadOnly("cell", 1, "col2", true);
    gridView2.setReadOnly("cell", 2, "col2", true);
    //senseReader="true"인 정적 그리드 
    gridView3.setReadOnly("cell", 1, "col1", true);
    gridView3.setReadOnly("cell", 2, "col1", true);
};
scwin.onpageunload = function() {};
scwin.makeGrid = function() {
    //기존 gridview 삭제 
    var gridViewObj = $p.getComponentById("gridView1");
    gridViewObj.remove();
    //새로운 gridview 생성 
    var gridViewStr = "";
    gridViewStr += '<w2:gridView xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms" dataList="dataList1" scrollByColumn="false" summaryAuto="false" scrollByColumnAdaptive="false" keyMoveEditMode="true" enterKeyMove="down" id="gridView1" style="width: 500px;height: 150px;"  ignoreCellClick="false" ignoreToggleOnDisabled="false" fixedColumnWithHidden="true" mergeCells="byrow" useShiftKey="true">';
    gridViewStr += '<w2:header id="header1" style="">';
    gridViewStr += '<w2:row id="row1" style="">';
    gridViewStr += '<w2:column blockSelect="false" id="column5" style="height:20px" inputType="text" width="100" displayMode="label" value="name1"></w2:column>';
    gridViewStr += '<w2:column blockSelect="false" id="column3" style="height:20px" inputType="text" width="70" displayMode="label" value="name1"></w2:column>';
    gridViewStr += '<w2:column blockSelect="false" id="column1" style="height:20px" width="70" inputType="text" displayMode="label" value="name3"></w2:column>';
    gridViewStr += '</w2:row>';
    gridViewStr += '</w2:header>';
    gridViewStr += '<w2:gBody id="gBody1" style="">';
    gridViewStr += '<w2:row id="row2" style="">';
    gridViewStr += '<w2:column blockSelect="false" id="col1" style="height:20px" inputType="calendar" width="100" ></w2:column>';
    gridViewStr += '<w2:column blockSelect="false" id="col2" style="height:20px" inputType="text" width="70" ></w2:column>';
    gridViewStr += '<w2:column blockSelect="false" id="col3" style="height:20px" width="70" inputType="text" ></w2:column>';
    gridViewStr += '</w2:row>';
    gridViewStr += '</w2:gBody>';
    gridViewStr += '</w2:gridView>';
    $p.dynamicCreate("gridView1", "gridView", gridViewStr, group1);
    gridView1.setReadOnly("cell", 1, "col1", true);
    gridView1.setReadOnly("cell", 2, "col1", true);
}
scwin.trigger1_onclick = function(e) {
    if (WebSquare.wUnit.getObjById("dataList1") != undefined) {
        $p.data.remove("dataList1");
    }
    //데이터 리스트 생성 및 정의 
    var option = {
        "id": "dataList1",
        "type": "dataList",
        "option": {
            "baseNode": "list",
            "repeatNode": "map"
        },
        "columnInfo": [{
            "id": "col1",
            "name": "name1",
            "dataType": "text"
        }, {
            "id": "col2",
            "name": "name1",
            "dataType": "text"
        }, {
            "id": "col3",
            "name": "name3",
            "dataType": "text"
        }]
    };
    $p.data.create(option);
    //데이터 리스트 데이터 값 세팅 
    dataList1.setJSON([{
        "col1": "20220125",
        "col2": "dataw2",
        "col3": "data3w"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }, {
        "col1": "",
        "col2": "2",
        "col3": "3"
    }]);
    scwin.makeGrid();
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.checkSimulate = function() {
    scwin.simulateWrapper('#G_gridView1__col1_input', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.checkSimulate2 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate2()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
